#!/usr/bin/env python3
from pathlib import Path
import base64, json, subprocess, zlib

ROOT=Path(__file__).resolve().parents[1]
PAYLOAD=''
files=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"))
for rel,text in files.items():
    path=ROOT/rel
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(text,encoding="utf-8")
subprocess.run(["python3",str(ROOT/"scripts"/"apply-release-hardening.py")],cwd=ROOT,check=True)
print(f"Bootstrapped {len(files)} release-hardening source files and applied migration.")
